@@ -0,0 +1,153 @@
+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.PetClinicTestBase;
+import ai.unifiedprocess.petclinic.UseCase;
+import ai.unifiedprocess.petclinic.core.ui.ApplicationErrorView;
+import ai.unifiedprocess.petclinic.vet.domain.Vet;
+import ai.unifiedprocess.petclinic.vet.domain.VetRepository;
+import ai.unifiedprocess.petclinic.welcome.ui.WelcomeView;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.sidenav.SideNavItem;
+import com.vaadin.flow.data.provider.Query;
+import org.jooq.DSLContext;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+import org.springframework.dao.DataAccessResourceFailureException;
+import org.springframework.test.context.bean.override.mockito.MockitoSpyBean;
+
+import java.util.List;
+
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VETS;
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VET_SPECIALTIES;
+import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+import static org.mockito.ArgumentMatchers.anyInt;
+import static org.mockito.Mockito.clearInvocations;
+import static org.mockito.Mockito.doThrow;
+import static org.mockito.Mockito.verify;
+import static org.mockito.Mockito.verifyNoMoreInteractions;
+
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+
+    @Autowired
+    private DSLContext dsl;
+
+    @MockitoSpyBean
+    private VetRepository repository;
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = {"BR-002", "BR-003"})
+    void navigationShowsNamesAndAlphabeticallyOrderedSpecialties() {
+        navigate(WelcomeView.class);
+        SideNavItem link = assertDoesNotThrow(() -> find(SideNavItem.class)
+                .withPropertyValue(SideNavItem::getLabel, "Veterinarians").single(),
+                "Expected Veterinarians navigation link");
+        UI.getCurrent().navigate(link.getPath());
+        assertEquals("vets", UI.getCurrent().getActiveViewLocation().getPath());
+
+        Grid<Vet> grid = grid();
+        assertEquals(List.of("First Name", "Last Name", "Specialties"),
+                grid.getColumns().stream().map(Grid.Column::getHeaderText).toList());
+        assertEquals(6, test(grid).size());
+        assertEquals("James", test(grid).getCellText(0, 0));
+        assertEquals("Carter", test(grid).getCellText(0, 1));
+        assertEquals("none", test(grid).getCellText(0, 2));
+        assertEquals("Linda", test(grid).getCellText(1, 0));
+        assertEquals("Douglas", test(grid).getCellText(1, 1));
+        assertEquals("dentistry, surgery", test(grid).getCellText(1, 2));
+        assertEquals("radiology", test(grid).getCellText(3, 2));
+        assertEquals(6, dsl.fetchCount(VETS), "Viewing must not modify veterinarians");
+        assertEquals(5, dsl.fetchCount(VET_SPECIALTIES), "Viewing must not modify specialties");
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void emptyDirectoryStillShowsTheGrid() {
+        dsl.deleteFrom(VET_SPECIALTIES).execute();
+        dsl.deleteFrom(VETS).execute();
+        navigate(VetView.class);
+        assertEquals(0, test(grid()).size());
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void gridFetchesBoundedDistinctChunksUntilTheEnd() {
+        for (int i = 0; i < 123; i++) {
+            dsl.insertInto(VETS, VETS.FIRST_NAME, VETS.LAST_NAME)
+                    .values("Test", "Vet").execute();
+        }
+        navigate(VetView.class);
+        Grid<Vet> grid = grid();
+        assertFalse(grid.getDataProvider().isInMemory());
+        assertEquals(129, test(grid).size());
+        clearInvocations(repository);
+        List<Vet> first = fetch(grid, 0, 50);
+        List<Vet> second = fetch(grid, 50, 50);
+        List<Vet> last = fetch(grid, 100, 50);
+        assertEquals(50, first.size());
+        assertEquals(50, second.size());
+        assertEquals(29, last.size());
+        assertTrue(fetch(grid, 129, 50).isEmpty());
+        assertEquals(129, java.util.stream.Stream.of(first, second, last)
+                .flatMap(List::stream).map(Vet::id).distinct().count());
+        verify(repository).findPage(0, 50);
+        verify(repository).findPage(50, 50);
+        verify(repository).findPage(100, 50);
+        verify(repository).findPage(129, 50);
+        verifyNoMoreInteractions(repository);
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void initialLoadFailureShowsApplicationErrorView() {
+        doThrow(new DataAccessResourceFailureException("Directory unavailable"))
+                .when(repository).count();
+        UI.getCurrent().navigate("vets");
+        // Simulate the first request for the grid's size after navigation.
+        if (!find(Grid.class).all().isEmpty()) {
+            grid().getDataProvider().size(new Query<>());
+        }
+        assertErrorView();
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void countFailureReplacesDirectoryWithApplicationErrorView() {
+        navigate(VetView.class);
+        Grid<Vet> grid = grid();
+        doThrow(new DataAccessResourceFailureException("Directory unavailable"))
+                .when(repository).count();
+        grid.getDataProvider().size(new Query<>());
+        assertErrorView();
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void laterPageFailureReplacesAlreadyLoadedDirectory() {
+        navigate(VetView.class);
+        Grid<Vet> grid = grid();
+        assertEquals(2, fetch(grid, 0, 2).size());
+        doThrow(new DataAccessResourceFailureException("Directory unavailable"))
+                .when(repository).findPage(anyInt(), anyInt());
+        assertTrue(fetch(grid, 2, 2).isEmpty());
+        assertErrorView();
+    }
+
+    private void assertErrorView() {
+        assertDoesNotThrow(() -> find(ApplicationErrorView.class).single(),
+                "Expected application error view after a data-access failure");
+        assertTrue(find(Grid.class).all().isEmpty(), "Failed directory must not remain visible");
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<Vet> grid() {
+        return assertDoesNotThrow(() -> find(Grid.class).single(), "Expected veterinarians grid");
+    }
+
+    private List<Vet> fetch(Grid<Vet> grid, int offset, int limit) {
+        return grid.getDataProvider().fetch(new Query<>(offset, limit, List.of(), null, null)).toList();
+    }
+}
